async function(vars) {
	var dataSource = await model.getDatasource({
		endpoint: "B2B/PurchaseOrderLine",
		odataAppend: "?$filter=PurchaseOrderId eq " + vars.purchaseOrderId + "&$orderby=LineNumber asc"
	});
	var lineGrid  = new GridWidget(vars.element, dataSource);
	lineGrid.editable = false;
	lineGrid.sortable = false;
	lineGrid.filterable = false;
	lineGrid.pageable = true;
	lineGrid.scrollable = false;
	lineGrid.groupable = false;
	lineGrid.columns = [
		{ field: "LineNumber", type: "number", title: "[resource_shortdisplayname[LineNumber]]", width: 70 },
		{ field: "Description", type: "string", title: "[resource_shortdisplayname[Description]]" },
		{ field: "LinePrice", type: "number", title: "[resource_shortdisplayname[LinePrice]]", format: "{0:" + type.moneyFormat + "}", width: 90, attributes:{style:"text-align:right;"} },
		{ field: "TaxAmount", type: "number", title: "[resource_shortdisplayname[TaxAmount]]", format: "{0:" + type.moneyFormat + "}", width: 90, attributes:{style:"text-align:right;"} },
		{ field: "CurrencyId", type: "string", title: "[resource_shortdisplayname[CurrencyId]]", width: 70 },
		{ field: "LastUpdated", type: "date", title: "[resource_shortdisplayname[LastUpdated]]", format: "{0:" + type.dateFormat + "}", width: 110 }
	];
	vars.PurchaseOrderLineGrid = lineGrid;
	return lineGrid;
}
